// Modo apresentação (#/aula) — design V3Apresentar (Aula kit): projector view, one question at a time,
// answer revealed only on request. Questions and answers are computed from the same LOLA + SPICE data.
// Source of truth: this .tsx file (Preact). aula.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment } from "../../vendor/preact/preact.module.js";
import { num } from "../../ds/components.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { Badge, mount } from "../../ds/ui.js";
import { loadComparison } from "./comparar.js";
import { LETTERS } from "./common.js";

/** The four questions. pick: "max" or "min" of the metric across sites. */
export const QUESTIONS = [
  { key: "sunPct", unit: "%", pick: "max", q: "Qual destes locais vê o Sol por mais tempo?", why: "Mais horas de Sol = mais energia possível. O relevo ao redor esconde o Sol baixo do polo." },
  { key: "longestBlackoutH", unit: "h", pick: "max", q: "Em qual local a Terra some por mais tempo seguido?", why: "Sem a Terra no céu, não há comunicação direta. Montanhas no caminho bloqueiam a linha de visada." },
  { key: "longestDarkH", unit: "h", pick: "max", q: "Qual local tem a noite mais longa?", why: "No polo, a noite depende do relevo, não só da hora do dia. Noite longa exige bateria maior." },
  { key: "bothPct", unit: "%", pick: "max", q: "Onde o Sol e a Terra aparecem juntos por mais tempo?", why: "Para pousar, queremos energia e comunicação ao mesmo tempo." },
];
const short = (n: string) => n.replace(/\s*\(.*\)$/, "");
const fmt = (v: number, u: string) => (u === "%" ? num(v, 0, "%") : num(v, 0, " h"));

export async function render(outlet: HTMLElement, ctx: RouteCtx): Promise<void> {
  const { sc, result } = await loadComparison(ctx);
  const rows = result.rows;
  const qi = Math.min(QUESTIONS.length, Math.max(1, Number(ctx.query.q) || 1)) - 1;
  const Q = QUESTIONS[qi];
  const reveal = ctx.query.r === "1";
  const vals = rows.map(r => (r.computed ? (r.w as never as Record<string, number>)[Q.key] : NaN));
  const finite = vals.filter(Number.isFinite);
  const target = finite.length ? (Q.pick === "max" ? Math.max(...finite) : Math.min(...finite)) : NaN;
  const go = (patch: Record<string, string | null>) => buildHash("/aula", { ...ctx.query, ...patch });

  // timer (not persisted); stops when the view is replaced. Imperative on purpose: it mutates two text nodes every second.
  let secs = 0, timer: ReturnType<typeof setInterval> | null = null;
  let tLabel!: HTMLElement;
  const onTimer = (e: Event) => {
    const tBtn = e.currentTarget as HTMLButtonElement;
    if (timer) { clearInterval(timer); timer = null; tBtn.textContent = "Continuar"; tBtn.setAttribute("aria-pressed", "false"); return; }
    tBtn.textContent = "Pausar"; tBtn.setAttribute("aria-pressed", "true");
    timer = setInterval(() => {
      if (!tLabel.isConnected) { clearInterval(timer!); return; }
      secs++; tLabel.textContent = Math.floor(secs / 60) + ":" + String(secs % 60).padStart(2, "0");
    }, 1000);
  };

  mount(outlet, <div class="present">
    <div class="row wrap"><span class="chipg">{"Pergunta " + (qi + 1) + " de " + QUESTIONS.length}</span>
      <span class="row"><Badge kind="est" /><span class="t2">{"Janela de " + sc.days + " dias · dados LOLA + SPICE"}</span></span>
      <span class="row"><span class="num" ref={(el: HTMLElement | null) => { if (el) tLabel = el; }}>0:00</span>
        <button type="button" class="btnG" aria-pressed={false} onClick={onTimer}>Iniciar cronômetro</button></span></div>
    <h1 class="q" data-route-title="">{Q.q}</h1>
    <p class="sub t2">{reveal ? Q.why : "Converse com a turma antes de revelar."}</p>
    <div class="opts">{rows.map((r, i) => {
      const win = reveal && Number.isFinite(vals[i]) && vals[i] === target;
      return <div class={"opt solid" + (win ? " answer-yes" : "")}>
        <span class="lbl-s">{"Local " + LETTERS[i]}</span>
        <strong class="title-l">{short(r.name)}</strong>
        <span class="big">{reveal ? fmt(vals[i], Q.unit) : "?"}</span>
        {win ? <span class="chipa">✓ Resposta</span> : null}</div>;
    })}</div>
    <div class="row wrap">
      {reveal ? <a class="btnG" href={go({ r: null })}>Esconder resposta</a> : <a class="btnA" href={go({ r: "1" })}>Revelar resposta</a>}
      {qi > 0 ? <a class="btnG" href={go({ q: String(qi), r: null })}>← Pergunta anterior</a> : null}
      {qi < QUESTIONS.length - 1 ? <a class="btnL" href={go({ q: String(qi + 2), r: null })}>Próxima pergunta →</a> : null}
      <a class="chipg" href={buildHash("/aula/atividade", { ...ctx.query, q: null, r: null })}>Montar atividade</a>
    </div>
    <details class="notes glass card"><summary>Notas do professor</summary>
      <p class="t2">Os números são prévios e não revisados pela NASA. Visibilidade é geometria (relevo + efemérides), não um enlace de rádio nem um cálculo de energia. Use a pergunta para discutir por que o relevo importa no polo.</p></details>
  </div>);
}
